def is_positive(*args, **kwargs):
    """Validator: check if all numeric arguments are positive"""
    for arg in args:
        if isinstance(arg, (int, float)) and arg <= 0:
            raise ValueError("All numeric arguments must be positive")

@validate_input(is_positive)
def calculate_area(length, width):
    return length * width

print("Testing debug decorator:")
add_numbers(1, 2, 3, 4, 5)

print("\nTesting retry decorator:")
try:
    result = unreliable_function()
    print(f"  Result: {result}")
except Exception as e:
    print(f"  Failed after retries: {e}")

print("\nTesting validation decorator:")
try:
    area = calculate_area(5, 3)
    print(f"  Area: {area}")
except ValueError as e:
    print(f"  Validation failed: {e}")

try:
    area = calculate_area(-5, 3)  # Should fail validation
    print(f"  Area: {area}")
except ValueError as e:
    print(f"  Validation failed: {e}")

