print("\n\n7. ADVANCED PATTERNS")
print("=" * 50)

def create_processor(*processors):
    """Create a function that applies multiple processors"""
    def process_data(*args, **kwargs):
        result = args
        for processor in processors:
            result = processor(*result, **kwargs)
        return result
    return process_data

def memoize(func):
    """Simple memoization decorator"""
    cache = {}
    def wrapper(*args, **kwargs):
        # Create a key from args and kwargs
        key = str(args) + str(sorted(kwargs.items()))
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    return wrapper
