Create a flexible API endpoint

```python
def create_api_endpoint(*required_fields, **optional_config):
    """Create a flexible API endpoint"""
    def endpoint_handler(**request_data):
        # Validate required fields
        missing_fields = set(required_fields) - set(request_data.keys())
        if missing_fields:
            raise ValueError(f"Missing required fields: {missing_fields}")

        # Apply optional configuration
        response_format = optional_config.get('format', 'json')
        include_metadata = optional_config.get('include_metadata', True)

        # Process the request
        result = {
            'data': request_data,
            'status': 'success'
        }

        if include_metadata:
            result['metadata'] = {
                'timestamp': time.time(),
                'fields_processed': len(request_data)
            }

        return result

    return endpoint_handler
